def dedupe_support_roles(apps, schema_editor):
    """Merge duplicate (job, user) support rows before the unique constraint:
    keep the oldest, re-point the extras' cash-outs onto it, delete extras."""
    from django.db.models import Count

    JobSupportTeamRole = apps.get_model("jobtracker", "JobSupportTeamRole")
    SupportBudgetDraw = apps.get_model("jobtracker", "SupportBudgetDraw")
    dupes = (
        JobSupportTeamRole.objects.filter(user__isnull=False)
        .values("job_id", "user_id")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    merged = 0
    for d in dupes:
        rows = list(
            JobSupportTeamRole.objects.filter(
                job_id=d["job_id"], user_id=d["user_id"]
            ).order_by("pk")
        )
        keep, extras = rows[0], rows[1:]
        for extra in extras:
            SupportBudgetDraw.objects.filter(support_role=extra).update(
                support_role=keep
            )
            extra.delete()
            merged += 1
    if merged:
        print("\n  Merged {} duplicate support role row(s).".format(merged))


